1	package nexusfixture
2	
3	import (
4		"net"
5		"net/http"
6		"net/netip"
7		"regexp"
8		"sort"
9		"strings"
10	)
11	
12	// Leak is one finding of CheckLeaks. It names where and which rule, never what
13	// matched: a field for the matched text would put a secret in a test log.
14	type Leak struct {
15		Fixture string
16		Line    int // 1-based
17		Rule    string
18	}
19	
20	// AllowedHosts are the only hosts a fixture may name, in a URL or a Host
21	// header: the loopback address the bench is published on and the bench's own
22	// proxy upstream (the one internal/nexusbench/testdata/descriptor.example.json
23	// names). The bench's LAN addresses are not allowed.
24	var AllowedHosts = []string{"127.0.0.1", "bench-upstream.nexus-bench.svc.cluster.local"}
25	
26	// The rules, by the name a Leak carries.
27	const (
28		ruleAuthorization  = "authorization-not-redacted"
29		ruleSession        = "cookie-or-session"
30		ruleHeaderAllowed  = "response-header-outside-allowlist"
31		ruleJWT            = "jwt-like-value"
32		ruleJSONSecret     = "REDACTED"
33		ruleHost           = "host-not-allowed"
34		rulePrivateAddress = "private-or-link-local-address"
35		ruleInternalName   = "internal-name-or-path"
36		ruleExactTerm      = "exact-term"
37	)
38	
39	// sessionKV is the name of the Nexus session cookie, refused anywhere in a fixture.
40	const sessionKV = "NXSESSIONID"
41	
42	var (
43		jwtLike  = regexp.MustCompile(`eyJ[A-Za-z0-9_-]{10,}`)
44		urlAuth  = regexp.MustCompile(`(?i)https?://([^\s/"'<>?#\\,;)]+)`)
45		ipv4Like = regexp.MustCompile(`\b\d{1,3}(?:\.\d{1,3}){3}\b`)
46	
47		sessionHeaders = []string{"cookie", "set-cookie", "x-nexus-ui"}
48		// internalNames are matched ignoring case; internalPaths exactly, because
49		// "/users/" is a legitimate Nexus REST path.
50		internalNames = []string{"datomir", "secrets.json", "xdg_state_home"}
51		internalPaths = []string{"/home/", "/Users/"}
52	)
53	
54	// lineState is where a line sits in the file: the commented header, or one of
55	// the parts of an exchange.
56	type lineState int
57	
58	const (
59		stMeta lineState = iota
60		stReqLine
61		stReqHeaders
62		stRespLine
63		stRespHeaders
64		stBody
65	)
66	
67	// CheckLeaks scans one fixture, line by line (lines count from 1), for what a
68	// fixture must not hold: an Authorization other than the placeholders, a cookie
69	// or session header, a response header outside ResponseHeaderAllowlist, a
70	// JWT-like value, a JSON secret key whose value is not "<redacted>", a host
71	// outside AllowedHosts, a private or link-local address, an internal name or
72	// local path, and each term of exact (recorder passwords and their Basic
73	// encodings, or an external deny list; an empty term matches nothing). The text
74	// is scanned as written, not parsed: a file that does not parse is still checked.
75	func CheckLeaks(fixture string, data []byte, exact []string) []Leak {
76		c := &leakScan{fixture: fixture, seen: map[leakKey]bool{}}
77		text := string(data)
78		state := stMeta
79		for i, line := range strings.Split(text, "\n") {
80			state = c.scanLine(i+1, line, state, exact)
81		}
82		c.scanJSONSecrets(text)
83		sort.SliceStable(c.leaks, func(i, j int) bool { return c.leaks[i].Line < c.leaks[j].Line })
84		return c.leaks
85	}
86	
87	type leakKey struct {
88		line int
89		rule string
90	}
91	
92	type leakScan struct {
93		fixture string
94		leaks   []Leak
95		seen    map[leakKey]bool
96	}
97	
98	// add records a rule once per line.
99	func (c *leakScan) add(line int, rule string) {
100		k := leakKey{line, rule}
101		if c.seen[k] {
102			return
103		}
104		c.seen[k] = true
105		c.leaks = append(c.leaks, Leak{Fixture: c.fixture, Line: line, Rule: rule})
106	}
107	
108	// scanLine checks one line and returns the state of the next.
109	func (c *leakScan) scanLine(n int, line string, state lineState, exact []string) lineState {
110		if line == exchangeSep && state != stMeta {
111			return stReqLine
112		}
113		if state == stReqHeaders || state == stRespHeaders {
114			c.scanHeader(n, line, state)
115		}
116		c.scanText(n, line, exact)
117		return nextState(state, line)
118	}
119	
120	func nextState(state lineState, line string) lineState {
121		switch state {
122		case stMeta:
123			if line == "" {
124				return stReqLine
125			}
126		case stReqLine:
127			return stReqHeaders
128		case stReqHeaders:
129			if line == "" {
130				return stRespLine
131			}
132		case stRespLine:
133			return stRespHeaders
134		case stRespHeaders:
135			if line == "" {
136				return stBody
137			}
138		}
139		return state
140	}
141	
142	func (c *leakScan) scanHeader(n int, line string, state lineState) {
143		name, value, ok := strings.Cut(line, ":")
144		if !ok {
145			return
146		}
147		name, value = strings.TrimSpace(name), strings.TrimSpace(value)
148		lower := strings.ToLower(name)
149		switch {
150		case lower == "authorization" && value != authBasicRedacted && value != authBearerRedacted:
151			c.add(n, ruleAuthorization)
152		case contains(sessionHeaders, lower):
153			c.add(n, ruleSession)
154		}
155		if state == stRespHeaders && !allowedResponseHeader(name) {
156			c.add(n, ruleHeaderAllowed)
157		}
158		if state == stReqHeaders && lower == "host" && !allowedHost(value) {
159			c.add(n, ruleHost)
160		}
161	}
162	
163	func allowedResponseHeader(name string) bool {
164		canonical := http.CanonicalHeaderKey(name)
165		for _, a := range ResponseHeaderAllowlist {
166			if http.CanonicalHeaderKey(a) == canonical {
167				return true
168			}
169		}
170		return false
171	}
172	
173	// scanText applies the rules that hold on any line, header or body.
174	func (c *leakScan) scanText(n int, line string, exact []string) {
175		if strings.Contains(strings.ToUpper(line), sessionKV) {
176			c.add(n, ruleSession)
177		}
178		if jwtLike.MatchString(line) {
179			c.add(n, ruleJWT)
180		}
181		for _, m := range urlAuth.FindAllStringSubmatch(line, -1) {
182			if !allowedAuthority(m[1]) {
183				c.add(n, ruleHost)
184			}
185		}
186		for _, ip := range ipv4Like.FindAllString(line, -1) {
187			if addr, err := netip.ParseAddr(ip); err == nil && (addr.IsPrivate() || addr.IsLinkLocalUnicast()) {
188				c.add(n, rulePrivateAddress)
189			}
190		}
191		lower := strings.ToLower(line)
192		for _, name := range internalNames {
193			if strings.Contains(lower, name) {
194				c.add(n, ruleInternalName)
195			}
196		}
197		for _, p := range internalPaths {
198			if strings.Contains(line, p) {
199				c.add(n, ruleInternalName)
200			}
201		}
202		for _, term := range exact {
203			if term != "" && strings.Contains(line, term) {
204				c.add(n, ruleExactTerm)
205			}
206		}
207	}
208	
209	// scanJSONSecrets runs over the whole text, not line by line, because Redact
210	// replaces a secret value wherever it sits relative to its key. The leak is
211	// reported at the line of the key.
212	func (c *leakScan) scanJSONSecrets(text string) {
213		for _, m := range secretJSON.FindAllStringSubmatchIndex(text, -1) {
214			value := text[m[4]:m[5]]
215			if value == `"`+redacted+`"` || value == "null" {
216				continue
217			}
218			c.add(strings.Count(text[:m[0]], "\n")+1, ruleJSONSecret)
219		}
220	}
221	
222	// allowedAuthority checks the authority of a URL: no user info, and a host in
223	// AllowedHosts.
224	func allowedAuthority(authority string) bool {
225		if strings.Contains(authority, "@") {
226			return false
227		}
228		return allowedHost(authority)
229	}
230	
231	// allowedHost checks a host with or without a port.
232	func allowedHost(hostPort string) bool {
233		host := hostPort
234		if h, _, err := net.SplitHostPort(hostPort); err == nil {
235			host = h
236		}
237		host = strings.Trim(strings.ToLower(host), "[]")
238		return contains(AllowedHosts, host)
239	}
240

